def common_prefix(left, right):
    # Initialize the result with the first character of both strings
    result = left[0]

    # Iterate over the strings, comparing characters from the start
    for i in range(1, min(len(left), len(right))):
        # If characters don't match, return the current result
        if left[i] != right[i]:
            return result

    # If all characters match, return the entire result
    return result
